import copy,json,pathlib,subprocess,tempfile,sys
script=pathlib.Path(__file__).with_name('verify_current23_inputs.py');source='a'*40;fixture={'id':'synthetic-contract'};profile={'fps':24,'resolution':[360,360]};row={'fixture':fixture,'variant':'v3','status':'PASS','sha256':'newvideo','input':{'lyrics':'exact original'},'referenceInputs':{'audioSHA256':'originalwav'},'sourceInvariant':{'pcmHash':'originalpcm'},'provenance':{'finalArtifactVerification':{'status':'MEASURED','binding':{'sourceCommit':source,'videoSHA256':'newvideo','outputProfile':profile}}}}
spec={'sourceCommit':source,'fixtures':[fixture],'expectedOriginalConditions':[{'fixture':fixture['id'],'input':row['input'],'audioWAVSHA256':'originalwav','pcmHash':'originalpcm','outputProfile':profile,'originalVideoSHA256':'oldvideo'}]}
cases=[('matched',lambda x:None,True),('wrong_pcm',lambda x:x['sourceInvariant'].update(pcmHash='other'),False),('wrong_wav',lambda x:x['referenceInputs'].update(audioSHA256='other'),False),('other_input',lambda x:x['input'].update(lyrics='other'),False),('wrong_source',lambda x:x['provenance']['finalArtifactVerification']['binding'].update(sourceCommit='b'*40),False),('wrong_movie',lambda x:x.update(sha256='othermovie'),False),('unmeasured',lambda x:x['provenance']['finalArtifactVerification'].update(status='UNMEASURED'),False),('other_profile',lambda x:x['provenance']['finalArtifactVerification']['binding'].update(outputProfile={'fps':30}),False)]
with tempfile.TemporaryDirectory() as tmp:
 p=pathlib.Path(tmp);(p/'matrix').mkdir();(p/'spec.json').write_text(json.dumps(spec))
 for name,mutate,valid in cases:
  trial=copy.deepcopy(row);mutate(trial);(p/'matrix/results.json').write_text(json.dumps({'rows':[trial]}));r=subprocess.run([sys.executable,str(script),str(p),str(p/'spec.json'),fixture['id']],capture_output=True);assert (r.returncode==0)==valid,(name,r.stdout,r.stderr)
print(json.dumps({'pass':len(cases),'fail':0,'scope':'Strict input/audio/profile/source/movie identity and measured FAV counterexamples'}))
